CREATE OR REPLACE FUNCTION "__mj"."spUpdateAIAgentArtifactType"(
    p_id UUID,
    p_agentid UUID DEFAULT NULL,
    p_artifacttypeid UUID DEFAULT NULL,
    p_sequence_clear boolean DEFAULT false,
    p_sequence int DEFAULT NULL
) RETURNS SETOF "__mj"."vwAIAgentArtifactTypes" AS $$
DECLARE
    v_updated_count INTEGER;
BEGIN
    UPDATE "__mj"."AIAgentArtifactType"
    SET
        "AgentID" = COALESCE(p_agentid, "AgentID"),
        "ArtifactTypeID" = COALESCE(p_artifacttypeid, "ArtifactTypeID"),
        "Sequence" = CASE WHEN p_sequence_clear = true THEN NULL ELSE COALESCE(p_sequence, "Sequence") END
    WHERE
        "ID" = p_id;

    GET DIAGNOSTICS v_updated_count = ROW_COUNT;

    IF v_updated_count = 0 THEN
        -- Nothing was updated, return empty result set
        RETURN;
    END IF;

    -- Return the updated record from the base view
    RETURN QUERY
    SELECT * FROM "__mj"."vwAIAgentArtifactTypes"
    WHERE "ID" = p_id;
END;
$$ LANGUAGE plpgsql;
