CREATE OR REPLACE FUNCTION "__mj"."spCreateAIAgentLearningCycle"(
    p_id UUID DEFAULT NULL,
    p_agentid UUID DEFAULT NULL,
    p_startedat TIMESTAMPTZ DEFAULT NULL,
    p_endedat_clear boolean DEFAULT false,
    p_endedat TIMESTAMPTZ DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL,
    p_agentsummary_clear boolean DEFAULT false,
    p_agentsummary TEXT DEFAULT NULL
) RETURNS SETOF "__mj"."vwAIAgentLearningCycles" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."AIAgentLearningCycle"
        (
            "ID",
            "AgentID",
                "StartedAt",
                "EndedAt",
                "Status",
                "AgentSummary"
        )
    VALUES
        (
            v_new_id,
            p_agentid,
                COALESCE(p_startedat, NOW()),
                CASE WHEN p_endedat_clear = true THEN NULL ELSE COALESCE(p_endedat, NULL) END,
                p_status,
                CASE WHEN p_agentsummary_clear = true THEN NULL ELSE COALESCE(p_agentsummary, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwAIAgentLearningCycles"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
