CREATE OR REPLACE FUNCTION "__mj"."spUpdateAIAgentPrompt"(
    p_id UUID,
    p_agentid UUID DEFAULT NULL,
    p_promptid UUID DEFAULT NULL,
    p_purpose_clear boolean DEFAULT false,
    p_purpose TEXT DEFAULT NULL,
    p_executionorder int DEFAULT NULL,
    p_configurationid_clear boolean DEFAULT false,
    p_configurationid UUID DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL,
    p_contextbehavior varchar(50) DEFAULT NULL,
    p_contextmessagecount_clear boolean DEFAULT false,
    p_contextmessagecount int DEFAULT NULL
) RETURNS SETOF "__mj"."vwAIAgentPrompts" AS $$
DECLARE
    v_updated_count INTEGER;
BEGIN
    UPDATE "__mj"."AIAgentPrompt"
    SET
        "AgentID" = COALESCE(p_agentid, "AgentID"),
        "PromptID" = COALESCE(p_promptid, "PromptID"),
        "Purpose" = CASE WHEN p_purpose_clear = true THEN NULL ELSE COALESCE(p_purpose, "Purpose") END,
        "ExecutionOrder" = COALESCE(p_executionorder, "ExecutionOrder"),
        "ConfigurationID" = CASE WHEN p_configurationid_clear = true THEN NULL ELSE COALESCE(p_configurationid, "ConfigurationID") END,
        "Status" = COALESCE(p_status, "Status"),
        "ContextBehavior" = COALESCE(p_contextbehavior, "ContextBehavior"),
        "ContextMessageCount" = CASE WHEN p_contextmessagecount_clear = true THEN NULL ELSE COALESCE(p_contextmessagecount, "ContextMessageCount") END
    WHERE
        "ID" = p_id;

    GET DIAGNOSTICS v_updated_count = ROW_COUNT;

    IF v_updated_count = 0 THEN
        -- Nothing was updated, return empty result set
        RETURN;
    END IF;

