CREATE OR REPLACE FUNCTION "__mj"."spCreateAIAgentStepPath"(
    p_id UUID DEFAULT NULL,
    p_originstepid UUID DEFAULT NULL,
    p_destinationstepid UUID DEFAULT NULL,
    p_condition_clear boolean DEFAULT false,
    p_condition TEXT DEFAULT NULL,
    p_priority int DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description varchar(255) DEFAULT NULL,
    p_pathpoints_clear boolean DEFAULT false,
    p_pathpoints TEXT DEFAULT NULL
) RETURNS SETOF "__mj"."vwAIAgentStepPaths" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."AIAgentStepPath"
        (
            "ID",
            "OriginStepID",
                "DestinationStepID",
                "Condition",
                "Priority",
                "Description",
                "PathPoints"
        )
    VALUES
        (
            v_new_id,
            p_originstepid,
                p_destinationstepid,
                CASE WHEN p_condition_clear = true THEN NULL ELSE COALESCE(p_condition, NULL) END,
                COALESCE(p_priority, 0),
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                CASE WHEN p_pathpoints_clear = true THEN NULL ELSE COALESCE(p_pathpoints, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwAIAgentStepPaths"
    WHERE "ID" = v_new_id;
END;
