BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."AIAgentStep"
        (
            "ID",
            "AgentID",
                "Name",
                "Description",
                "StepType",
                "StartingStep",
                "TimeoutSeconds",
                "RetryCount",
                "OnErrorBehavior",
                "ActionID",
                "SubAgentID",
                "PromptID",
                "ActionOutputMapping",
                "PositionX",
                "PositionY",
                "Width",
                "Height",
                "Status",
                "ActionInputMapping",
                "LoopBodyType",
                "Configuration"
        )
    VALUES
        (
            v_new_id,
            p_agentid,
                p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                p_steptype,
                COALESCE(p_startingstep, FALSE),
                CASE WHEN p_timeoutseconds_clear = true THEN NULL ELSE COALESCE(p_timeoutseconds, 600) END,
                COALESCE(p_retrycount, 0),
                COALESCE(p_onerrorbehavior, 'fail'),
                CASE WHEN p_actionid_clear = true THEN NULL ELSE COALESCE(p_actionid, NULL) END,
                CASE WHEN p_subagentid_clear = true THEN NULL ELSE COALESCE(p_subagentid, NULL) END,
                CASE WHEN p_promptid_clear = true THEN NULL ELSE COALESCE(p_promptid, NULL) END,
                CASE WHEN p_actionoutputmapping_clear = true THEN NULL ELSE COALESCE(p_actionoutputmapping, NULL) END,
                COALESCE(p_positionx, 0),
                COALESCE(p_positiony, 0),
                COALESCE(p_width, 200),
                COALESCE(p_height, 80),
                COALESCE(p_status, 'Active'),
                CASE WHEN p_actioninputmapping_clear = true THEN NULL ELSE COALESCE(p_actioninputmapping, NULL) END,
                CASE WHEN p_loopbodytype_clear = true THEN NULL ELSE COALESCE(p_loopbodytype, NULL) END,
                CASE WHEN p_configuration_clear = true THEN NULL ELSE COALESCE(p_configuration, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwAIAgentSteps"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
