CREATE OR REPLACE FUNCTION "__mj"."spDeleteAIAgentStep"(
    p_id UUID
) RETURNS TABLE("ID" UUID) AS $$
#variable_conflict use_column
DECLARE
    v_affected_count INTEGER;
    v_rec RECORD;
BEGIN
    -- Cascade: Delete MJ: AI Agent Step Paths records via OriginStepID
    FOR v_rec IN
        SELECT "ID"
        FROM "__mj"."AIAgentStepPath"
        WHERE "OriginStepID" = p_id
    LOOP
        PERFORM "__mj"."spDeleteAIAgentStepPath"(v_rec."ID");
    END LOOP;

        -- Cascade: Delete MJ: AI Agent Step Paths records via DestinationStepID
    FOR v_rec IN
        SELECT "ID"
        FROM "__mj"."AIAgentStepPath"
        WHERE "DestinationStepID" = p_id
    LOOP
        PERFORM "__mj"."spDeleteAIAgentStepPath"(v_rec."ID");
    END LOOP;

    
    DELETE FROM "__mj"."AIAgentStep"
    WHERE "ID" = p_id;

    GET DIAGNOSTICS v_affected_count = ROW_COUNT;

    IF v_affected_count = 0 THEN
        RETURN QUERY SELECT NULL::UUID AS "ID";
    ELSE
        RETURN QUERY SELECT p_id AS "ID";
    END IF;
END;
$$ LANGUAGE plpgsql;
