                CASE WHEN p_instructionsoverride_clear = true THEN NULL ELSE COALESCE(p_instructionsoverride, NULL) END,
                COALESCE(p_calendarchannelmode, 'ReadOnly')
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwAIAgentUserPolicies"
