        RETURN;
    END IF;

    -- Return the updated record from the base view
    RETURN QUERY
    SELECT * FROM "__mj"."vwAIBridgeProviderChannels"
    WHERE "ID" = p_id;
END;
$$ LANGUAGE plpgsql;
