CREATE OR REPLACE FUNCTION "__mj"."spCreateAICredentialBinding"(
    p_id UUID DEFAULT NULL,
    p_credentialid UUID DEFAULT NULL,
    p_bindingtype varchar(20) DEFAULT NULL,
    p_aivendorid_clear boolean DEFAULT false,
    p_aivendorid UUID DEFAULT NULL,
    p_aimodelvendorid_clear boolean DEFAULT false,
    p_aimodelvendorid UUID DEFAULT NULL,
    p_aipromptmodelid_clear boolean DEFAULT false,
    p_aipromptmodelid UUID DEFAULT NULL,
    p_priority int DEFAULT NULL,
    p_isactive BOOLEAN DEFAULT NULL
) RETURNS SETOF "__mj"."vwAICredentialBindings" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."AICredentialBinding"
        (
            "ID",
            "CredentialID",
                "BindingType",
                "AIVendorID",
                "AIModelVendorID",
                "AIPromptModelID",
                "Priority",
                "IsActive"
        )
    VALUES
        (
            v_new_id,
            p_credentialid,
                p_bindingtype,
                CASE WHEN p_aivendorid_clear = true THEN NULL ELSE COALESCE(p_aivendorid, NULL) END,
                CASE WHEN p_aimodelvendorid_clear = true THEN NULL ELSE COALESCE(p_aimodelvendorid, NULL) END,
                CASE WHEN p_aipromptmodelid_clear = true THEN NULL ELSE COALESCE(p_aipromptmodelid, NULL) END,
                COALESCE(p_priority, 0),
                COALESCE(p_isactive, TRUE)
        )
    ;

