CREATE OR REPLACE FUNCTION "__mj"."spCreateAIModelAction"(
    p_id UUID DEFAULT NULL,
    p_aimodelid UUID DEFAULT NULL,
    p_aiactionid UUID DEFAULT NULL,
    p_isactive BOOLEAN DEFAULT NULL
) RETURNS SETOF "__mj"."vwAIModelActions" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."AIModelAction"
        (
            "ID",
            "AIModelID",
                "AIActionID",
                "IsActive"
        )
    VALUES
        (
            v_new_id,
            p_aimodelid,
                p_aiactionid,
                COALESCE(p_isactive, TRUE)
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwAIModelActions"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
