CREATE OR REPLACE FUNCTION "__mj"."spUpdateAIModelAction"(
    p_id UUID,
    p_aimodelid UUID DEFAULT NULL,
    p_aiactionid UUID DEFAULT NULL,
    p_isactive BOOLEAN DEFAULT NULL
) RETURNS SETOF "__mj"."vwAIModelActions" AS $$
DECLARE
    v_updated_count INTEGER;
BEGIN
    UPDATE "__mj"."AIModelAction"
    SET
        "AIModelID" = COALESCE(p_aimodelid, "AIModelID"),
        "AIActionID" = COALESCE(p_aiactionid, "AIActionID"),
        "IsActive" = COALESCE(p_isactive, "IsActive")
    WHERE
        "ID" = p_id;

    GET DIAGNOSTICS v_updated_count = ROW_COUNT;

    IF v_updated_count = 0 THEN
        -- Nothing was updated, return empty result set
        RETURN;
    END IF;

    -- Return the updated record from the base view
    RETURN QUERY
    SELECT * FROM "__mj"."vwAIModelActions"
    WHERE "ID" = p_id;
END;
$$ LANGUAGE plpgsql;
