                p_typeid,
                CASE WHEN p_supportsprefill_clear = true THEN NULL ELSE COALESCE(p_supportsprefill, NULL) END,
                CASE WHEN p_prefillfallbacktext_clear = true THEN NULL ELSE COALESCE(p_prefillfallbacktext, NULL) END,
