CREATE OR REPLACE FUNCTION "__mj"."spCreateAPIApplicationScope"(
    p_id UUID DEFAULT NULL,
    p_applicationid UUID DEFAULT NULL,
    p_scopeid UUID DEFAULT NULL,
    p_resourcepattern_clear boolean DEFAULT false,
    p_resourcepattern varchar(750) DEFAULT NULL,
    p_patterntype varchar(20) DEFAULT NULL,
    p_isdeny BOOLEAN DEFAULT NULL,
    p_priority int DEFAULT NULL,
    p_rowfilterid_clear boolean DEFAULT false,
    p_rowfilterid uuid DEFAULT NULL
) RETURNS SETOF "__mj"."vwAPIApplicationScopes" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."APIApplicationScope"
        (
            "ID",
            "ApplicationID",
                "ScopeID",
                "ResourcePattern",
                "PatternType",
                "IsDeny",
                "Priority",
                "RowFilterID"
        )
    VALUES
        (
            v_new_id,
            p_applicationid,
                p_scopeid,
                CASE WHEN p_resourcepattern_clear = true THEN NULL ELSE COALESCE(p_resourcepattern, NULL) END,
                COALESCE(p_patterntype, 'Include'),
                COALESCE(p_isdeny, FALSE),
                COALESCE(p_priority, 0),
                CASE WHEN p_rowfilterid_clear = true THEN NULL ELSE COALESCE(p_rowfilterid, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwAPIApplicationScopes"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
