-----               BASE TABLE:  ArchiveConfigurationEntity
-----               PRIMARY KEY: ID
------------------------------------------------------------
DO $vw_regen$
DECLARE
  vsql CONSTANT TEXT := $vsql$CREATE OR REPLACE VIEW "__mj"."vwArchiveConfigurationEntities"
AS
