    p_artifactid UUID DEFAULT NULL,
    p_userid UUID DEFAULT NULL,
    p_canread BOOLEAN DEFAULT NULL,
    p_canedit BOOLEAN DEFAULT NULL,
    p_candelete BOOLEAN DEFAULT NULL,
