    p_sharedbyuserid_clear boolean DEFAULT false,
    p_sharedbyuserid UUID DEFAULT NULL
) RETURNS SETOF "__mj"."vwArtifactPermissions" AS $$
DECLARE
    v_updated_count INTEGER;
BEGIN
    UPDATE "__mj"."ArtifactPermission"
    SET
        "ArtifactID" = COALESCE(p_artifactid, "ArtifactID"),
        "UserID" = COALESCE(p_userid, "UserID"),
        "CanRead" = COALESCE(p_canread, "CanRead"),
        "CanEdit" = COALESCE(p_canedit, "CanEdit"),
        "CanDelete" = COALESCE(p_candelete, "CanDelete"),
        "CanShare" = COALESCE(p_canshare, "CanShare"),
        "SharedByUserID" = CASE WHEN p_sharedbyuserid_clear = true THEN NULL ELSE COALESCE(p_sharedbyuserid, "SharedByUserID") END
    WHERE
