CREATE OR REPLACE FUNCTION "__mj"."spCreateClusterAnalysis"(
    p_id UUID DEFAULT NULL,
    p_name varchar(255) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_userid UUID DEFAULT NULL,
    p_entityid_clear boolean DEFAULT false,
    p_entityid UUID DEFAULT NULL,
    p_algorithm varchar(50) DEFAULT NULL,
    p_configuration_clear boolean DEFAULT false,
    p_configuration TEXT DEFAULT NULL,
    p_metrics_clear boolean DEFAULT false,
    p_metrics TEXT DEFAULT NULL,
    p_projectedpoints_clear boolean DEFAULT false,
    p_projectedpoints TEXT DEFAULT NULL,
    p_viewportstate_clear boolean DEFAULT false,
    p_viewportstate TEXT DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL
) RETURNS SETOF "__mj"."vwClusterAnalysis" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."ClusterAnalysis"
        (
            "ID",
            "Name",
                "Description",
                "UserID",
                "EntityID",
                "Algorithm",
                "Configuration",
                "Metrics",
                "ProjectedPoints",
                "ViewportState",
                "Status"
        )
    VALUES
        (
            v_new_id,
            p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                p_userid,
                CASE WHEN p_entityid_clear = true THEN NULL ELSE COALESCE(p_entityid, NULL) END,
                COALESCE(p_algorithm, 'KMeans'),
                CASE WHEN p_configuration_clear = true THEN NULL ELSE COALESCE(p_configuration, NULL) END,
                CASE WHEN p_metrics_clear = true THEN NULL ELSE COALESCE(p_metrics, NULL) END,
                CASE WHEN p_projectedpoints_clear = true THEN NULL ELSE COALESCE(p_projectedpoints, NULL) END,
                CASE WHEN p_viewportstate_clear = true THEN NULL ELSE COALESCE(p_viewportstate, NULL) END,
                COALESCE(p_status, 'Complete')
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwClusterAnalysis"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
