CREATE OR REPLACE FUNCTION "__mj"."spCreateCollectionPermission"(
    p_id UUID DEFAULT NULL,
    p_collectionid UUID DEFAULT NULL,
    p_userid UUID DEFAULT NULL,
    p_canread BOOLEAN DEFAULT NULL,
    p_canshare BOOLEAN DEFAULT NULL,
    p_canedit BOOLEAN DEFAULT NULL,
    p_candelete BOOLEAN DEFAULT NULL,
    p_sharedbyuserid_clear boolean DEFAULT false,
    p_sharedbyuserid UUID DEFAULT NULL
) RETURNS SETOF "__mj"."vwCollectionPermissions" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."CollectionPermission"
        (
            "ID",
            "CollectionID",
                "UserID",
                "CanRead",
                "CanShare",
                "CanEdit",
                "CanDelete",
                "SharedByUserID"
        )
    VALUES
        (
            v_new_id,
            p_collectionid,
                p_userid,
                COALESCE(p_canread, TRUE),
                COALESCE(p_canshare, FALSE),
                COALESCE(p_canedit, FALSE),
                COALESCE(p_candelete, FALSE),
                CASE WHEN p_sharedbyuserid_clear = true THEN NULL ELSE COALESCE(p_sharedbyuserid, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwCollectionPermissions"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
