CREATE OR REPLACE FUNCTION "__mj"."spCreateCompanyIntegrationFieldMap"(
    p_id UUID DEFAULT NULL,
    p_entitymapid UUID DEFAULT NULL,
    p_sourcefieldname varchar(500) DEFAULT NULL,
    p_sourcefieldlabel_clear boolean DEFAULT false,
    p_sourcefieldlabel varchar(500) DEFAULT NULL,
    p_destinationfieldname varchar(500) DEFAULT NULL,
    p_destinationfieldlabel_clear boolean DEFAULT false,
    p_destinationfieldlabel varchar(500) DEFAULT NULL,
    p_direction varchar(50) DEFAULT NULL,
    p_transformpipeline_clear boolean DEFAULT false,
    p_transformpipeline TEXT DEFAULT NULL,
    p_iskeyfield BOOLEAN DEFAULT NULL,
    p_isrequired BOOLEAN DEFAULT NULL,
    p_defaultvalue_clear boolean DEFAULT false,
    p_defaultvalue TEXT DEFAULT NULL,
    p_priority int DEFAULT NULL,
    p_status varchar(50) DEFAULT NULL
) RETURNS SETOF "__mj"."vwCompanyIntegrationFieldMaps" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."CompanyIntegrationFieldMap"
        (
            "ID",
            "EntityMapID",
                "SourceFieldName",
                "SourceFieldLabel",
                "DestinationFieldName",
                "DestinationFieldLabel",
                "Direction",
                "TransformPipeline",
                "IsKeyField",
                "IsRequired",
                "DefaultValue",
                "Priority",
                "Status"
        )
    VALUES
        (
            v_new_id,
            p_entitymapid,
                p_sourcefieldname,
                CASE WHEN p_sourcefieldlabel_clear = true THEN NULL ELSE COALESCE(p_sourcefieldlabel, NULL) END,
                p_destinationfieldname,
                CASE WHEN p_destinationfieldlabel_clear = true THEN NULL ELSE COALESCE(p_destinationfieldlabel, NULL) END,
                COALESCE(p_direction, 'SourceToDest'),
                CASE WHEN p_transformpipeline_clear = true THEN NULL ELSE COALESCE(p_transformpipeline, NULL) END,
                COALESCE(p_iskeyfield, FALSE),
                COALESCE(p_isrequired, FALSE),
                CASE WHEN p_defaultvalue_clear = true THEN NULL ELSE COALESCE(p_defaultvalue, NULL) END,
                COALESCE(p_priority, 0),
                COALESCE(p_status, 'Active')
        )
    ;

