    p_watermarktype varchar(50) DEFAULT NULL,
    p_watermarkvalue_clear boolean DEFAULT false,
    p_watermarkvalue TEXT DEFAULT NULL,
    p_lastsyncat_clear boolean DEFAULT false,
    p_lastsyncat TIMESTAMPTZ DEFAULT NULL,
    p_recordssynced int DEFAULT NULL
) RETURNS SETOF "__mj"."vwCompanyIntegrationSyncWatermarks" AS $$
