        (
            "ID",
            "Name",
                "Description",
                "AIModelID",
                "MinTags",
                "MaxTags",
                "EmbeddingModelID",
                "VectorIndexID",
                "Configuration",
                "SegmenterKey",
                "CleanerKey",
                "ExtractorKey"
        )
