                "Configuration",
                "EntityID",
                "EntityDocumentID",
                "ScheduledJobID",
                "SegmenterKey",
                "CleanerKey",
                "FieldConfidence",
                "ForceDiscovery",
                "LastDiscoveredAt",
                "LastSyncedAt",
                "GraphID"
        )
    VALUES
        (
            v_new_id,
            CASE WHEN p_name_clear = true THEN NULL ELSE COALESCE(p_name, NULL) END,
                p_contenttypeid,
                p_contentsourcetypeid,
                p_contentfiletypeid,
                p_url,
                CASE WHEN p_embeddingmodelid_clear = true THEN NULL ELSE COALESCE(p_embeddingmodelid, NULL) END,
