CREATE OR REPLACE FUNCTION "__mj"."spCreateCredential"(
    p_id UUID DEFAULT NULL,
    p_credentialtypeid UUID DEFAULT NULL,
    p_categoryid_clear boolean DEFAULT false,
    p_categoryid UUID DEFAULT NULL,
    p_name varchar(200) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_values TEXT DEFAULT NULL,
    p_isdefault BOOLEAN DEFAULT NULL,
    p_isactive BOOLEAN DEFAULT NULL,
    p_expiresat_clear boolean DEFAULT false,
    p_expiresat TIMESTAMPTZ DEFAULT NULL,
    p_lastvalidatedat_clear boolean DEFAULT false,
    p_lastvalidatedat TIMESTAMPTZ DEFAULT NULL,
    p_lastusedat_clear boolean DEFAULT false,
    p_lastusedat TIMESTAMPTZ DEFAULT NULL,
