    p_iconclass varchar(100) DEFAULT NULL
) RETURNS SETOF "__mj"."vwCredentials" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."Credential"
        (
            "ID",
            "CredentialTypeID",
                "CategoryID",
                "Name",
                "Description",
                "Values",
                "IsDefault",
                "IsActive",
                "ExpiresAt",
                "LastValidatedAt",
                "LastUsedAt",
                "IconClass"
        )
    VALUES
        (
            v_new_id,
            p_credentialtypeid,
                CASE WHEN p_categoryid_clear = true THEN NULL ELSE COALESCE(p_categoryid, NULL) END,
                p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                p_values,
                COALESCE(p_isdefault, FALSE),
                COALESCE(p_isactive, TRUE),
                CASE WHEN p_expiresat_clear = true THEN NULL ELSE COALESCE(p_expiresat, NULL) END,
                CASE WHEN p_lastvalidatedat_clear = true THEN NULL ELSE COALESCE(p_lastvalidatedat, NULL) END,
                CASE WHEN p_lastusedat_clear = true THEN NULL ELSE COALESCE(p_lastusedat, NULL) END,
                CASE WHEN p_iconclass_clear = true THEN NULL ELSE COALESCE(p_iconclass, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwCredentials"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
