CREATE OR REPLACE FUNCTION "__mj"."spCreateDashboardCategoryPermission"(
    p_id UUID DEFAULT NULL,
    p_dashboardcategoryid UUID DEFAULT NULL,
    p_userid UUID DEFAULT NULL,
    p_canread BOOLEAN DEFAULT NULL,
    p_canedit BOOLEAN DEFAULT NULL,
    p_canaddremove BOOLEAN DEFAULT NULL,
    p_canshare BOOLEAN DEFAULT NULL,
    p_sharedbyuserid_clear boolean DEFAULT false,
    p_sharedbyuserid UUID DEFAULT NULL
) RETURNS SETOF "__mj"."vwDashboardCategoryPermissions" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."DashboardCategoryPermission"
        (
            "ID",
            "DashboardCategoryID",
                "UserID",
                "CanRead",
                "CanEdit",
                "CanAddRemove",
                "CanShare",
                "SharedByUserID"
        )
    VALUES
        (
            v_new_id,
            p_dashboardcategoryid,
                p_userid,
                COALESCE(p_canread, TRUE),
                COALESCE(p_canedit, FALSE),
                COALESCE(p_canaddremove, FALSE),
                COALESCE(p_canshare, FALSE),
                CASE WHEN p_sharedbyuserid_clear = true THEN NULL ELSE COALESCE(p_sharedbyuserid, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwDashboardCategoryPermissions"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
