CREATE OR REPLACE FUNCTION "__mj"."spCreateDatasetItem"(
    p_id UUID DEFAULT NULL,
    p_code varchar(50) DEFAULT NULL,
    p_datasetid UUID DEFAULT NULL,
    p_sequence int DEFAULT NULL,
    p_entityid UUID DEFAULT NULL,
    p_whereclause_clear boolean DEFAULT false,
    p_whereclause TEXT DEFAULT NULL,
    p_datefieldtocheck varchar(100) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_columns_clear boolean DEFAULT false,
    p_columns TEXT DEFAULT NULL
) RETURNS SETOF "__mj"."vwDatasetItems" AS $$
DECLARE
    v_new_id UUID;
BEGIN
