            "ID",
            "Code",
                "DatasetID",
                "Sequence",
                "EntityID",
                "WhereClause",
                "DateFieldToCheck",
                "Description",
                "Columns"
        )
    VALUES
        (
            v_new_id,
            p_code,
                p_datasetid,
                COALESCE(p_sequence, 0),
                p_entityid,
                CASE WHEN p_whereclause_clear = true THEN NULL ELSE COALESCE(p_whereclause, NULL) END,
                p_datefieldtocheck,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                CASE WHEN p_columns_clear = true THEN NULL ELSE COALESCE(p_columns, NULL) END
        )
