CREATE OR REPLACE FUNCTION "__mj"."spCreateDuplicateRunDetail"(
    p_id UUID DEFAULT NULL,
    p_duplicaterunid UUID DEFAULT NULL,
    p_recordid varchar(500) DEFAULT NULL,
    p_matchstatus varchar(20) DEFAULT NULL,
    p_skippedreason_clear boolean DEFAULT false,
    p_skippedreason TEXT DEFAULT NULL,
    p_matcherrormessage_clear boolean DEFAULT false,
    p_matcherrormessage TEXT DEFAULT NULL,
    p_mergestatus varchar(20) DEFAULT NULL,
    p_mergeerrormessage_clear boolean DEFAULT false,
    p_mergeerrormessage TEXT DEFAULT NULL,
    p_recordmetadata_clear boolean DEFAULT false,
    p_recordmetadata TEXT DEFAULT NULL,
    p_startedat_clear boolean DEFAULT false,
    p_startedat TIMESTAMPTZ DEFAULT NULL,
    p_endedat_clear boolean DEFAULT false,
    p_endedat TIMESTAMPTZ DEFAULT NULL
) RETURNS SETOF "__mj"."vwDuplicateRunDetails" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."DuplicateRunDetail"
        (
            "ID",
            "DuplicateRunID",
                "RecordID",
                "MatchStatus",
                "SkippedReason",
                "MatchErrorMessage",
                "MergeStatus",
                "MergeErrorMessage",
                "RecordMetadata",
                "StartedAt",
                "EndedAt"
        )
    VALUES
        (
            v_new_id,
            p_duplicaterunid,
                p_recordid,
                COALESCE(p_matchstatus, 'Pending'),
                CASE WHEN p_skippedreason_clear = true THEN NULL ELSE COALESCE(p_skippedreason, NULL) END,
                CASE WHEN p_matcherrormessage_clear = true THEN NULL ELSE COALESCE(p_matcherrormessage, NULL) END,
                COALESCE(p_mergestatus, 'Not Applicable'),
                CASE WHEN p_mergeerrormessage_clear = true THEN NULL ELSE COALESCE(p_mergeerrormessage, NULL) END,
                CASE WHEN p_recordmetadata_clear = true THEN NULL ELSE COALESCE(p_recordmetadata, NULL) END,
                CASE WHEN p_startedat_clear = true THEN NULL ELSE COALESCE(p_startedat, NULL) END,
                CASE WHEN p_endedat_clear = true THEN NULL ELSE COALESCE(p_endedat, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwDuplicateRunDetails"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
