CREATE OR REPLACE FUNCTION "__mj"."spUpdateDuplicateRunDetail"(
    p_id UUID,
    p_duplicaterunid UUID DEFAULT NULL,
    p_recordid varchar(500) DEFAULT NULL,
    p_matchstatus varchar(20) DEFAULT NULL,
    p_skippedreason_clear boolean DEFAULT false,
    p_skippedreason TEXT DEFAULT NULL,
    p_matcherrormessage_clear boolean DEFAULT false,
    p_matcherrormessage TEXT DEFAULT NULL,
    p_mergestatus varchar(20) DEFAULT NULL,
    p_mergeerrormessage_clear boolean DEFAULT false,
    p_mergeerrormessage TEXT DEFAULT NULL,
    p_recordmetadata_clear boolean DEFAULT false,
    p_recordmetadata TEXT DEFAULT NULL,
    p_startedat_clear boolean DEFAULT false,
    p_startedat TIMESTAMPTZ DEFAULT NULL,
    p_endedat_clear boolean DEFAULT false,
    p_endedat TIMESTAMPTZ DEFAULT NULL
) RETURNS SETOF "__mj"."vwDuplicateRunDetails" AS $$
DECLARE
    v_updated_count INTEGER;
BEGIN
    UPDATE "__mj"."DuplicateRunDetail"
    SET
        "DuplicateRunID" = COALESCE(p_duplicaterunid, "DuplicateRunID"),
        "RecordID" = COALESCE(p_recordid, "RecordID"),
        "MatchStatus" = COALESCE(p_matchstatus, "MatchStatus"),
        "SkippedReason" = CASE WHEN p_skippedreason_clear = true THEN NULL ELSE COALESCE(p_skippedreason, "SkippedReason") END,
        "MatchErrorMessage" = CASE WHEN p_matcherrormessage_clear = true THEN NULL ELSE COALESCE(p_matcherrormessage, "MatchErrorMessage") END,
        "MergeStatus" = COALESCE(p_mergestatus, "MergeStatus"),
        "MergeErrorMessage" = CASE WHEN p_mergeerrormessage_clear = true THEN NULL ELSE COALESCE(p_mergeerrormessage, "MergeErrorMessage") END,
        "RecordMetadata" = CASE WHEN p_recordmetadata_clear = true THEN NULL ELSE COALESCE(p_recordmetadata, "RecordMetadata") END,
        "StartedAt" = CASE WHEN p_startedat_clear = true THEN NULL ELSE COALESCE(p_startedat, "StartedAt") END,
        "EndedAt" = CASE WHEN p_endedat_clear = true THEN NULL ELSE COALESCE(p_endedat, "EndedAt") END
    WHERE
        "ID" = p_id;

    GET DIAGNOSTICS v_updated_count = ROW_COUNT;

    IF v_updated_count = 0 THEN
        -- Nothing was updated, return empty result set
        RETURN;
    END IF;

    -- Return the updated record from the base view
    RETURN QUERY
    SELECT * FROM "__mj"."vwDuplicateRunDetails"
    WHERE "ID" = p_id;
END;
$$ LANGUAGE plpgsql;
