CREATE OR REPLACE FUNCTION "__mj"."spCreateEncryptionKey"(
    p_id UUID DEFAULT NULL,
    p_name varchar(100) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_encryptionkeysourceid UUID DEFAULT NULL,
    p_encryptionalgorithmid UUID DEFAULT NULL,
    p_keylookupvalue varchar(500) DEFAULT NULL,
    p_keyversion varchar(20) DEFAULT NULL,
    p_marker varchar(20) DEFAULT NULL,
    p_isactive BOOLEAN DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL,
    p_activatedat_clear boolean DEFAULT false,
    p_activatedat TIMESTAMPTZ DEFAULT NULL,
    p_expiresat_clear boolean DEFAULT false,
    p_expiresat TIMESTAMPTZ DEFAULT NULL
) RETURNS SETOF "__mj"."vwEncryptionKeys" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."EncryptionKey"
        (
            "ID",
            "Name",
                "Description",
                "EncryptionKeySourceID",
                "EncryptionAlgorithmID",
                "KeyLookupValue",
                "KeyVersion",
                "Marker",
                "IsActive",
                "Status",
                "ActivatedAt",
                "ExpiresAt"
        )
    VALUES
        (
            v_new_id,
            p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                p_encryptionkeysourceid,
                p_encryptionalgorithmid,
                p_keylookupvalue,
                COALESCE(p_keyversion, '1'),
                COALESCE(p_marker, '$ENC$'),
                COALESCE(p_isactive, TRUE),
                COALESCE(p_status, 'Active'),
                CASE WHEN p_activatedat_clear = true THEN NULL ELSE COALESCE(p_activatedat, NULL) END,
                CASE WHEN p_expiresat_clear = true THEN NULL ELSE COALESCE(p_expiresat, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwEncryptionKeys"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
