CREATE OR REPLACE FUNCTION "__mj"."spUpdateEncryptionKey"(
    p_id UUID,
    p_name varchar(100) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_encryptionkeysourceid UUID DEFAULT NULL,
    p_encryptionalgorithmid UUID DEFAULT NULL,
    p_keylookupvalue varchar(500) DEFAULT NULL,
    p_keyversion varchar(20) DEFAULT NULL,
    p_marker varchar(20) DEFAULT NULL,
    p_isactive BOOLEAN DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL,
    p_activatedat_clear boolean DEFAULT false,
    p_activatedat TIMESTAMPTZ DEFAULT NULL,
    p_expiresat_clear boolean DEFAULT false,
    p_expiresat TIMESTAMPTZ DEFAULT NULL
) RETURNS SETOF "__mj"."vwEncryptionKeys" AS $$
DECLARE
    v_updated_count INTEGER;
BEGIN
    UPDATE "__mj"."EncryptionKey"
    SET
        "Name" = COALESCE(p_name, "Name"),
        "Description" = CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, "Description") END,
        "EncryptionKeySourceID" = COALESCE(p_encryptionkeysourceid, "EncryptionKeySourceID"),
        "EncryptionAlgorithmID" = COALESCE(p_encryptionalgorithmid, "EncryptionAlgorithmID"),
        "KeyLookupValue" = COALESCE(p_keylookupvalue, "KeyLookupValue"),
        "KeyVersion" = COALESCE(p_keyversion, "KeyVersion"),
        "Marker" = COALESCE(p_marker, "Marker"),
        "IsActive" = COALESCE(p_isactive, "IsActive"),
        "Status" = COALESCE(p_status, "Status"),
        "ActivatedAt" = CASE WHEN p_activatedat_clear = true THEN NULL ELSE COALESCE(p_activatedat, "ActivatedAt") END,
        "ExpiresAt" = CASE WHEN p_expiresat_clear = true THEN NULL ELSE COALESCE(p_expiresat, "ExpiresAt") END
    WHERE
        "ID" = p_id;

    GET DIAGNOSTICS v_updated_count = ROW_COUNT;

    IF v_updated_count = 0 THEN
        -- Nothing was updated, return empty result set
        RETURN;
    END IF;

    -- Return the updated record from the base view
    RETURN QUERY
    SELECT * FROM "__mj"."vwEncryptionKeys"
    WHERE "ID" = p_id;
END;
$$ LANGUAGE plpgsql;
