    "e"."ReasoningPromptID" = MJAIPrompt_ReasoningPromptID."ID"
LEFT OUTER JOIN
    "__mj"."AIAgent" AS MJAIAgent_ReasoningAgentID
  ON
    "e"."ReasoningAgentID" = MJAIAgent_ReasoningAgentID."ID"
$vsql$;
  rec RECORD;
BEGIN
  EXECUTE vsql;
EXCEPTION WHEN invalid_table_definition THEN
