CREATE OR REPLACE FUNCTION "__mj"."spCreateEntityDocumentRun"(
    p_id UUID DEFAULT NULL,
    p_entitydocumentid UUID DEFAULT NULL,
    p_startedat_clear boolean DEFAULT false,
    p_startedat TIMESTAMPTZ DEFAULT NULL,
    p_endedat_clear boolean DEFAULT false,
    p_endedat TIMESTAMPTZ DEFAULT NULL,
    p_status varchar(15) DEFAULT NULL
) RETURNS SETOF "__mj"."vwEntityDocumentRuns" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."EntityDocumentRun"
        (
            "ID",
            "EntityDocumentID",
                "StartedAt",
                "EndedAt",
                "Status"
        )
    VALUES
        (
            v_new_id,
            p_entitydocumentid,
                CASE WHEN p_startedat_clear = true THEN NULL ELSE COALESCE(p_startedat, NULL) END,
                CASE WHEN p_endedat_clear = true THEN NULL ELSE COALESCE(p_endedat, NULL) END,
                COALESCE(p_status, 'Pending')
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwEntityDocumentRuns"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
