  ON
    "f"."AIModelID" = MJAIModel_AIModelID."ID"
LEFT OUTER JOIN
    "__mj"."Test" AS MJTest_GoldenSetTestID
  ON
    "f"."GoldenSetTestID" = MJTest_GoldenSetTestID."ID"
LEFT OUTER JOIN
