CREATE OR REPLACE FUNCTION "__mj"."spCreateFile"(
    p_id UUID DEFAULT NULL,
    p_name varchar(500) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_categoryid_clear boolean DEFAULT false,
    p_categoryid UUID DEFAULT NULL,
    p_providerid UUID DEFAULT NULL,
    p_contenttype_clear boolean DEFAULT false,
    p_contenttype varchar(255) DEFAULT NULL,
    p_providerkey_clear boolean DEFAULT false,
    p_providerkey varchar(500) DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL
) RETURNS SETOF "__mj"."vwFiles" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."File"
        (
            "ID",
            "Name",
                "Description",
                "CategoryID",
                "ProviderID",
                "ContentType",
                "ProviderKey",
                "Status"
        )
    VALUES
        (
            v_new_id,
            p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                CASE WHEN p_categoryid_clear = true THEN NULL ELSE COALESCE(p_categoryid, NULL) END,
                p_providerid,
                CASE WHEN p_contenttype_clear = true THEN NULL ELSE COALESCE(p_contenttype, NULL) END,
                CASE WHEN p_providerkey_clear = true THEN NULL ELSE COALESCE(p_providerkey, NULL) END,
                COALESCE(p_status, 'Pending')
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwFiles"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
