CREATE OR REPLACE FUNCTION "__mj"."spUpdateFile"(
    p_id UUID,
    p_name varchar(500) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_categoryid_clear boolean DEFAULT false,
    p_categoryid UUID DEFAULT NULL,
    p_providerid UUID DEFAULT NULL,
    p_contenttype_clear boolean DEFAULT false,
    p_contenttype varchar(255) DEFAULT NULL,
    p_providerkey_clear boolean DEFAULT false,
    p_providerkey varchar(500) DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL
) RETURNS SETOF "__mj"."vwFiles" AS $$
DECLARE
    v_updated_count INTEGER;
BEGIN
    UPDATE "__mj"."File"
    SET
        "Name" = COALESCE(p_name, "Name"),
        "Description" = CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, "Description") END,
        "CategoryID" = CASE WHEN p_categoryid_clear = true THEN NULL ELSE COALESCE(p_categoryid, "CategoryID") END,
        "ProviderID" = COALESCE(p_providerid, "ProviderID"),
        "ContentType" = CASE WHEN p_contenttype_clear = true THEN NULL ELSE COALESCE(p_contenttype, "ContentType") END,
        "ProviderKey" = CASE WHEN p_providerkey_clear = true THEN NULL ELSE COALESCE(p_providerkey, "ProviderKey") END,
        "Status" = COALESCE(p_status, "Status")
    WHERE
        "ID" = p_id;

    GET DIAGNOSTICS v_updated_count = ROW_COUNT;

    IF v_updated_count = 0 THEN
        -- Nothing was updated, return empty result set
        RETURN;
    END IF;

    -- Return the updated record from the base view
    RETURN QUERY
    SELECT * FROM "__mj"."vwFiles"
    WHERE "ID" = p_id;
END;
$$ LANGUAGE plpgsql;
