    p_entityid_clear boolean DEFAULT false,
    p_entityid uuid DEFAULT NULL,
    p_recordid_clear boolean DEFAULT false,
    p_recordid text DEFAULT NULL,
    p_payloadjson_clear boolean DEFAULT false,
    p_payloadjson text DEFAULT NULL,
    p_status text DEFAULT NULL,
    p_expiresat timestamptz DEFAULT NULL,
    p_claimedat_clear boolean DEFAULT false,
    p_claimedat timestamptz DEFAULT NULL,
    p_claimedbyuserid_clear boolean DEFAULT false,
    p_claimedbyuserid uuid DEFAULT NULL,
    p_magiclinkinviteid_clear boolean DEFAULT false,
    p_magiclinkinviteid uuid DEFAULT NULL,
    p_metadatajson_clear boolean DEFAULT false,
    p_metadatajson text DEFAULT NULL
) RETURNS SETOF "__mj"."vwIdentityClaims" AS $$
DECLARE
    v_new_id uuid;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."IdentityClaim"
        (
            "ID",
            "ClaimTypeID",
                "NormalizedEmail",
                "EntityID",
                "RecordID",
                "PayloadJSON",
                "Status",
                "ExpiresAt",
                "ClaimedAt",
                "ClaimedByUserID",
                "MagicLinkInviteID",
                "MetadataJSON"
        )
    VALUES
        (
            v_new_id,
            p_claimtypeid,
                p_normalizedemail,
                CASE WHEN p_entityid_clear = true THEN NULL ELSE COALESCE(p_entityid, NULL) END,
                CASE WHEN p_recordid_clear = true THEN NULL ELSE COALESCE(p_recordid, NULL) END,
                CASE WHEN p_payloadjson_clear = true THEN NULL ELSE COALESCE(p_payloadjson, NULL) END,
                COALESCE(p_status, 'Pending'),
                p_expiresat,
                CASE WHEN p_claimedat_clear = true THEN NULL ELSE COALESCE(p_claimedat, NULL) END,
                CASE WHEN p_claimedbyuserid_clear = true THEN NULL ELSE COALESCE(p_claimedbyuserid, NULL) END,
                CASE WHEN p_magiclinkinviteid_clear = true THEN NULL ELSE COALESCE(p_magiclinkinviteid, NULL) END,
                CASE WHEN p_metadatajson_clear = true THEN NULL ELSE COALESCE(p_metadatajson, NULL) END
        )
