CREATE OR REPLACE FUNCTION "__mj"."spCreateMCPServerConnectionTool"(
    p_id UUID DEFAULT NULL,
    p_mcpserverconnectionid UUID DEFAULT NULL,
    p_mcpservertoolid UUID DEFAULT NULL,
    p_isenabled BOOLEAN DEFAULT NULL,
    p_defaultinputvalues_clear boolean DEFAULT false,
    p_defaultinputvalues TEXT DEFAULT NULL,
    p_maxcallsperminute_clear boolean DEFAULT false,
    p_maxcallsperminute int DEFAULT NULL
) RETURNS SETOF "__mj"."vwMCPServerConnectionTools" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."MCPServerConnectionTool"
        (
            "ID",
            "MCPServerConnectionID",
                "MCPServerToolID",
                "IsEnabled",
                "DefaultInputValues",
                "MaxCallsPerMinute"
        )
    VALUES
        (
            v_new_id,
            p_mcpserverconnectionid,
                p_mcpservertoolid,
                COALESCE(p_isenabled, TRUE),
                CASE WHEN p_defaultinputvalues_clear = true THEN NULL ELSE COALESCE(p_defaultinputvalues, NULL) END,
                CASE WHEN p_maxcallsperminute_clear = true THEN NULL ELSE COALESCE(p_maxcallsperminute, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwMCPServerConnectionTools"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
