                "AutoSyncTools",
                "AutoGenerateActions",
                "LogToolCalls",
                "LogInputParameters",
                "LogOutputContent",
                "MaxOutputLogSize",
                "LastConnectedAt",
                "LastErrorMessage",
                "EnvironmentVars"
        )
