    p_recommendationlevel varchar(20) DEFAULT NULL,
    p_rationale_clear boolean DEFAULT false,
    p_rationale TEXT DEFAULT NULL
) RETURNS SETOF "__mj"."vwMLAlgorithmUseCaseRankings" AS $$
DECLARE
