) RETURNS SETOF "__mj"."vwMeetings" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."Meeting"
        (
            "ID",
            "Title",
                "Description",
                "HostUserID",
                "RoomName",
                "Status",
                "ScheduledStartAt",
                "ScheduledEndAt",
