CREATE OR REPLACE FUNCTION "__mj"."spCreateOAuthToken"(
    p_id UUID DEFAULT NULL,
    p_mcpserverconnectionid UUID DEFAULT NULL,
    p_credentialid_clear boolean DEFAULT false,
    p_credentialid UUID DEFAULT NULL,
    p_tokentype varchar(50) DEFAULT NULL,
    p_expiresat TIMESTAMPTZ DEFAULT NULL,
    p_scope_clear boolean DEFAULT false,
    p_scope varchar(500) DEFAULT NULL,
    p_issuerurl varchar(1000) DEFAULT NULL,
    p_lastrefreshat_clear boolean DEFAULT false,
    p_lastrefreshat TIMESTAMPTZ DEFAULT NULL,
    p_refreshcount int DEFAULT NULL
) RETURNS SETOF "__mj"."vwOAuthTokens" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."OAuthToken"
        (
            "ID",
            "MCPServerConnectionID",
                "CredentialID",
                "TokenType",
                "ExpiresAt",
                "Scope",
                "IssuerURL",
                "LastRefreshAt",
                "RefreshCount"
        )
    VALUES
        (
            v_new_id,
            p_mcpserverconnectionid,
                CASE WHEN p_credentialid_clear = true THEN NULL ELSE COALESCE(p_credentialid, NULL) END,
                COALESCE(p_tokentype, 'Bearer'),
                p_expiresat,
                CASE WHEN p_scope_clear = true THEN NULL ELSE COALESCE(p_scope, NULL) END,
                p_issuerurl,
                CASE WHEN p_lastrefreshat_clear = true THEN NULL ELSE COALESCE(p_lastrefreshat, NULL) END,
                COALESCE(p_refreshcount, 0)
