    p_responsetypes TEXT DEFAULT NULL,
    p_scope_clear boolean DEFAULT false,
    p_scope varchar(500) DEFAULT NULL,
    p_status varchar(50) DEFAULT NULL,
    p_registrationresponse TEXT DEFAULT NULL
) RETURNS SETOF "__mj"."vwOAuthClientRegistrations" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
