CREATE OR REPLACE FUNCTION "__mj"."spUpdateOpenAppDependency"(
    p_id UUID,
    p_openappid UUID DEFAULT NULL,
    p_dependsonappname varchar(64) DEFAULT NULL,
    p_dependsonappid_clear boolean DEFAULT false,
    p_dependsonappid UUID DEFAULT NULL,
