    p_installedversion_clear boolean DEFAULT false,
    p_installedversion varchar(50) DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL
) RETURNS SETOF "__mj"."vwOpenAppDependencies" AS $$
DECLARE
    v_updated_count INTEGER;
BEGIN
    UPDATE "__mj"."OpenAppDependency"
    SET
        "OpenAppID" = COALESCE(p_openappid, "OpenAppID"),
        "DependsOnAppName" = COALESCE(p_dependsonappname, "DependsOnAppName"),
        "DependsOnAppID" = CASE WHEN p_dependsonappid_clear = true THEN NULL ELSE COALESCE(p_dependsonappid, "DependsOnAppID") END,
