        "InstalledVersion" = CASE WHEN p_installedversion_clear = true THEN NULL ELSE COALESCE(p_installedversion, "InstalledVersion") END,
        "Status" = COALESCE(p_status, "Status")
    WHERE
        "ID" = p_id;

    GET DIAGNOSTICS v_updated_count = ROW_COUNT;

    IF v_updated_count = 0 THEN
        -- Nothing was updated, return empty result set
        RETURN;
    END IF;

