CREATE OR REPLACE FUNCTION "__mj"."spCreateQueryDependency"(
    p_id UUID DEFAULT NULL,
    p_queryid UUID DEFAULT NULL,
    p_dependsonqueryid UUID DEFAULT NULL,
    p_referencepath varchar(500) DEFAULT NULL,
