    p_alias varchar(100) DEFAULT NULL,
    p_parametermapping_clear boolean DEFAULT false,
    p_parametermapping TEXT DEFAULT NULL,
    p_detectionmethod varchar(20) DEFAULT NULL
) RETURNS SETOF "__mj"."vwQueryDependencies" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."QueryDependency"
        (
            "ID",
            "QueryID",
                "DependsOnQueryID",
                "ReferencePath",
                "Alias",
                "ParameterMapping",
                "DetectionMethod"
        )
    VALUES
        (
            v_new_id,
            p_queryid,
                p_dependsonqueryid,
                p_referencepath,
                CASE WHEN p_alias_clear = true THEN NULL ELSE COALESCE(p_alias, NULL) END,
                CASE WHEN p_parametermapping_clear = true THEN NULL ELSE COALESCE(p_parametermapping, NULL) END,
                COALESCE(p_detectionmethod, 'Auto')
