CREATE OR REPLACE FUNCTION "__mj"."spUpdateRecordChangeReplayRun"(
    p_id UUID,
    p_startedat TIMESTAMPTZ DEFAULT NULL,
    p_endedat_clear boolean DEFAULT false,
    p_endedat TIMESTAMPTZ DEFAULT NULL,
    p_status varchar(50) DEFAULT NULL,
    p_userid UUID DEFAULT NULL
) RETURNS SETOF "__mj"."vwRecordChangeReplayRuns" AS $$
DECLARE
    v_updated_count INTEGER;
BEGIN
    UPDATE "__mj"."RecordChangeReplayRun"
    SET
        "StartedAt" = COALESCE(p_startedat, "StartedAt"),
        "EndedAt" = CASE WHEN p_endedat_clear = true THEN NULL ELSE COALESCE(p_endedat, "EndedAt") END,
        "Status" = COALESCE(p_status, "Status"),
        "UserID" = COALESCE(p_userid, "UserID")
    WHERE
        "ID" = p_id;

    GET DIAGNOSTICS v_updated_count = ROW_COUNT;

    IF v_updated_count = 0 THEN
        -- Nothing was updated, return empty result set
        RETURN;
    END IF;

    -- Return the updated record from the base view
    RETURN QUERY
    SELECT * FROM "__mj"."vwRecordChangeReplayRuns"
    WHERE "ID" = p_id;
END;
$$ LANGUAGE plpgsql;
