CREATE OR REPLACE FUNCTION "__mj"."spCreateRecommendationItem"(
    p_id UUID DEFAULT NULL,
    p_recommendationid UUID DEFAULT NULL,
    p_destinationentityid UUID DEFAULT NULL,
    p_destinationentityrecordid varchar(450) DEFAULT NULL,
    p_matchprobability_clear boolean DEFAULT false,
    p_matchprobability decimal(18, 15) DEFAULT NULL
) RETURNS SETOF "__mj"."vwRecommendationItems" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."RecommendationItem"
        (
            "ID",
            "RecommendationID",
                "DestinationEntityID",
                "DestinationEntityRecordID",
                "MatchProbability"
        )
    VALUES
        (
            v_new_id,
            p_recommendationid,
                p_destinationentityid,
                p_destinationentityrecordid,
                CASE WHEN p_matchprobability_clear = true THEN NULL ELSE COALESCE(p_matchprobability, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwRecommendationItems"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
