            "ID",
            "RecordCloneLogID",
                "EntityID",
                "SourceRecordID",
                "TargetRecordID",
                "Depth",
                "Route",
                "Status",
                "Sequence",
                "Reason",
                "FieldChangesJSON"
        )
    VALUES
        (
            v_new_id,
            p_recordclonelogid,
                p_entityid,
                p_sourcerecordid,
                CASE WHEN p_targetrecordid_clear = true THEN NULL ELSE COALESCE(p_targetrecordid, NULL) END,
                COALESCE(p_depth, 0),
                p_route,
                p_status,
                COALESCE(p_sequence, 0),
                CASE WHEN p_reason_clear = true THEN NULL ELSE COALESCE(p_reason, NULL) END,
