CREATE OR REPLACE FUNCTION "__mj"."spCreateRecordMergeLog"(
    p_id UUID DEFAULT NULL,
    p_entityid UUID DEFAULT NULL,
    p_survivingrecordid varchar(450) DEFAULT NULL,
    p_initiatedbyuserid UUID DEFAULT NULL,
    p_approvalstatus varchar(10) DEFAULT NULL,
    p_approvedbyuserid_clear boolean DEFAULT false,
    p_approvedbyuserid UUID DEFAULT NULL,
    p_processingstatus varchar(10) DEFAULT NULL,
    p_processingstartedat TIMESTAMPTZ DEFAULT NULL,
    p_processingendedat_clear boolean DEFAULT false,
    p_processingendedat TIMESTAMPTZ DEFAULT NULL,
    p_processinglog_clear boolean DEFAULT false,
    p_processinglog TEXT DEFAULT NULL,
    p_comments_clear boolean DEFAULT false,
    p_comments TEXT DEFAULT NULL
) RETURNS SETOF "__mj"."vwRecordMergeLogs" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."RecordMergeLog"
        (
            "ID",
            "EntityID",
                "SurvivingRecordID",
                "InitiatedByUserID",
                "ApprovalStatus",
                "ApprovedByUserID",
                "ProcessingStatus",
                "ProcessingStartedAt",
                "ProcessingEndedAt",
                "ProcessingLog",
                "Comments"
        )
    VALUES
        (
            v_new_id,
            p_entityid,
                p_survivingrecordid,
                p_initiatedbyuserid,
                COALESCE(p_approvalstatus, 'Pending'),
                CASE WHEN p_approvedbyuserid_clear = true THEN NULL ELSE COALESCE(p_approvedbyuserid, NULL) END,
                COALESCE(p_processingstatus, 'Pending'),
                COALESCE(p_processingstartedat, NOW()),
                CASE WHEN p_processingendedat_clear = true THEN NULL ELSE COALESCE(p_processingendedat, NULL) END,
                CASE WHEN p_processinglog_clear = true THEN NULL ELSE COALESCE(p_processinglog, NULL) END,
                CASE WHEN p_comments_clear = true THEN NULL ELSE COALESCE(p_comments, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwRecordMergeLogs"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
