CREATE OR REPLACE FUNCTION "__mj"."spUpdateResourceLink"(
    p_id UUID,
    p_userid UUID DEFAULT NULL,
    p_resourcetypeid UUID DEFAULT NULL,
    p_resourcerecordid varchar(255) DEFAULT NULL,
    p_folderid_clear boolean DEFAULT false,
    p_folderid varchar(255) DEFAULT NULL
) RETURNS SETOF "__mj"."vwResourceLinks" AS $$
DECLARE
