DECLARE
    v_affected_count INTEGER;
    v_rec RECORD;
BEGIN
    -- Cascade: Delete MJ: Rubric Evaluation Scores records via EvaluationID
    FOR v_rec IN
        SELECT "ID"
        FROM "__mj"."RubricEvaluationScore"
        WHERE "EvaluationID" = p_id
