CREATE OR REPLACE FUNCTION "__mj"."spCreateSearchScopeProvider"(
    p_id UUID DEFAULT NULL,
    p_searchscopeid UUID DEFAULT NULL,
    p_searchproviderid UUID DEFAULT NULL,
    p_enabled BOOLEAN DEFAULT NULL,
    p_maxresultsoverride_clear boolean DEFAULT false,
    p_maxresultsoverride int DEFAULT NULL,
    p_providerconfigoverride_clear boolean DEFAULT false,
    p_providerconfigoverride TEXT DEFAULT NULL,
    p_querytransformtemplateid_clear boolean DEFAULT false,
    p_querytransformtemplateid UUID DEFAULT NULL
) RETURNS SETOF "__mj"."vwSearchScopeProviders" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."SearchScopeProvider"
        (
            "ID",
            "SearchScopeID",
                "SearchProviderID",
                "Enabled",
                "MaxResultsOverride",
                "ProviderConfigOverride",
                "QueryTransformTemplateID"
        )
    VALUES
        (
            v_new_id,
            p_searchscopeid,
                p_searchproviderid,
                COALESCE(p_enabled, TRUE),
                CASE WHEN p_maxresultsoverride_clear = true THEN NULL ELSE COALESCE(p_maxresultsoverride, NULL) END,
                CASE WHEN p_providerconfigoverride_clear = true THEN NULL ELSE COALESCE(p_providerconfigoverride, NULL) END,
                CASE WHEN p_querytransformtemplateid_clear = true THEN NULL ELSE COALESCE(p_querytransformtemplateid, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwSearchScopeProviders"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
