CREATE OR REPLACE FUNCTION "__mj"."spCreateStateProvince"(
    p_id UUID DEFAULT NULL,
    p_countryid UUID DEFAULT NULL,
    p_name varchar(200) DEFAULT NULL,
    p_code varchar(10) DEFAULT NULL,
    p_iso3166_2 varchar(10) DEFAULT NULL,
    p_latitude_clear boolean DEFAULT false,
    p_latitude decimal(10, 6) DEFAULT NULL,
    p_longitude_clear boolean DEFAULT false,
    p_longitude decimal(10, 6) DEFAULT NULL,
    p_boundarygeojson_clear boolean DEFAULT false,
    p_boundarygeojson TEXT DEFAULT NULL,
    p_commonaliases_clear boolean DEFAULT false,
    p_commonaliases TEXT DEFAULT NULL
) RETURNS SETOF "__mj"."vwStateProvinces" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."StateProvince"
        (
            "ID",
            "CountryID",
                "Name",
                "Code",
                "ISO3166_2",
                "Latitude",
                "Longitude",
                "BoundaryGeoJSON",
                "CommonAliases"
        )
    VALUES
        (
            v_new_id,
            p_countryid,
                p_name,
                p_code,
                p_iso3166_2,
                CASE WHEN p_latitude_clear = true THEN NULL ELSE COALESCE(p_latitude, NULL) END,
                CASE WHEN p_longitude_clear = true THEN NULL ELSE COALESCE(p_longitude, NULL) END,
                CASE WHEN p_boundarygeojson_clear = true THEN NULL ELSE COALESCE(p_boundarygeojson, NULL) END,
                CASE WHEN p_commonaliases_clear = true THEN NULL ELSE COALESCE(p_commonaliases, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwStateProvinces"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
GRANT EXECUTE ON FUNCTION "__mj"."spCreateStateProvince" TO "cdp_Developer";
GRANT EXECUTE ON FUNCTION "__mj"."spCreateStateProvince" TO "cdp_Integration";


