CREATE OR REPLACE FUNCTION "__mj"."spUpdateStateProvince"(
    p_id UUID,
    p_countryid UUID DEFAULT NULL,
    p_name varchar(200) DEFAULT NULL,
    p_code varchar(10) DEFAULT NULL,
    p_iso3166_2 varchar(10) DEFAULT NULL,
    p_latitude_clear boolean DEFAULT false,
    p_latitude decimal(10, 6) DEFAULT NULL,
    p_longitude_clear boolean DEFAULT false,
    p_longitude decimal(10, 6) DEFAULT NULL,
    p_boundarygeojson_clear boolean DEFAULT false,
    p_boundarygeojson TEXT DEFAULT NULL,
    p_commonaliases_clear boolean DEFAULT false,
    p_commonaliases TEXT DEFAULT NULL
) RETURNS SETOF "__mj"."vwStateProvinces" AS $$
DECLARE
    v_updated_count INTEGER;
BEGIN
    UPDATE "__mj"."StateProvince"
    SET
        "CountryID" = COALESCE(p_countryid, "CountryID"),
        "Name" = COALESCE(p_name, "Name"),
        "Code" = COALESCE(p_code, "Code"),
        "ISO3166_2" = COALESCE(p_iso3166_2, "ISO3166_2"),
        "Latitude" = CASE WHEN p_latitude_clear = true THEN NULL ELSE COALESCE(p_latitude, "Latitude") END,
        "Longitude" = CASE WHEN p_longitude_clear = true THEN NULL ELSE COALESCE(p_longitude, "Longitude") END,
        "BoundaryGeoJSON" = CASE WHEN p_boundarygeojson_clear = true THEN NULL ELSE COALESCE(p_boundarygeojson, "BoundaryGeoJSON") END,
        "CommonAliases" = CASE WHEN p_commonaliases_clear = true THEN NULL ELSE COALESCE(p_commonaliases, "CommonAliases") END
    WHERE
        "ID" = p_id;

    GET DIAGNOSTICS v_updated_count = ROW_COUNT;

    IF v_updated_count = 0 THEN
        -- Nothing was updated, return empty result set
        RETURN;
    END IF;

    -- Return the updated record from the base view
    RETURN QUERY
    SELECT * FROM "__mj"."vwStateProvinces"
    WHERE "ID" = p_id;
END;
$$ LANGUAGE plpgsql;
