    p_isactive BOOLEAN DEFAULT NULL
) RETURNS SETOF "__mj"."vwTemplateContents" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."TemplateContent"
        (
            "ID",
            "TemplateID",
                "TypeID",
                "TemplateText",
                "Priority",
                "IsActive"
        )
    VALUES
        (
            v_new_id,
            p_templateid,
                p_typeid,
                CASE WHEN p_templatetext_clear = true THEN NULL ELSE COALESCE(p_templatetext, NULL) END,
                p_priority,
                COALESCE(p_isactive, TRUE)
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwTemplateContents"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
