    p_id UUID,
    p_templateid UUID DEFAULT NULL,
    p_typeid UUID DEFAULT NULL,
    p_templatetext_clear boolean DEFAULT false,
    p_templatetext TEXT DEFAULT NULL,
    p_priority int DEFAULT NULL,
    p_isactive BOOLEAN DEFAULT NULL
) RETURNS SETOF "__mj"."vwTemplateContents" AS $$
DECLARE
    v_updated_count INTEGER;
BEGIN
    UPDATE "__mj"."TemplateContent"
    SET
        "TemplateID" = COALESCE(p_templateid, "TemplateID"),
        "TypeID" = COALESCE(p_typeid, "TypeID"),
