CREATE OR REPLACE FUNCTION "__mj"."spCreateTestRubric"(
    p_id UUID DEFAULT NULL,
    p_typeid UUID DEFAULT NULL,
    p_name varchar(255) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_prompttemplate_clear boolean DEFAULT false,
    p_prompttemplate TEXT DEFAULT NULL,
    p_criteria_clear boolean DEFAULT false,
    p_criteria TEXT DEFAULT NULL,
    p_version_clear boolean DEFAULT false,
    p_version varchar(50) DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL
) RETURNS SETOF "__mj"."vwTestRubrics" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."TestRubric"
        (
            "ID",
            "TypeID",
                "Name",
                "Description",
                "PromptTemplate",
                "Criteria",
                "Version",
                "Status"
        )
    VALUES
        (
            v_new_id,
            p_typeid,
                p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                CASE WHEN p_prompttemplate_clear = true THEN NULL ELSE COALESCE(p_prompttemplate, NULL) END,
                CASE WHEN p_criteria_clear = true THEN NULL ELSE COALESCE(p_criteria, NULL) END,
                CASE WHEN p_version_clear = true THEN NULL ELSE COALESCE(p_version, NULL) END,
                COALESCE(p_status, 'Active')
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwTestRubrics"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
