CREATE OR REPLACE FUNCTION "__mj"."spUpdateTestRubric"(
    p_id UUID,
    p_typeid UUID DEFAULT NULL,
    p_name varchar(255) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_prompttemplate_clear boolean DEFAULT false,
    p_prompttemplate TEXT DEFAULT NULL,
    p_criteria_clear boolean DEFAULT false,
    p_criteria TEXT DEFAULT NULL,
    p_version_clear boolean DEFAULT false,
    p_version varchar(50) DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL
) RETURNS SETOF "__mj"."vwTestRubrics" AS $$
DECLARE
    v_updated_count INTEGER;
BEGIN
    UPDATE "__mj"."TestRubric"
    SET
        "TypeID" = COALESCE(p_typeid, "TypeID"),
        "Name" = COALESCE(p_name, "Name"),
        "Description" = CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, "Description") END,
        "PromptTemplate" = CASE WHEN p_prompttemplate_clear = true THEN NULL ELSE COALESCE(p_prompttemplate, "PromptTemplate") END,
        "Criteria" = CASE WHEN p_criteria_clear = true THEN NULL ELSE COALESCE(p_criteria, "Criteria") END,
        "Version" = CASE WHEN p_version_clear = true THEN NULL ELSE COALESCE(p_version, "Version") END,
        "Status" = COALESCE(p_status, "Status")
    WHERE
        "ID" = p_id;

    GET DIAGNOSTICS v_updated_count = ROW_COUNT;

    IF v_updated_count = 0 THEN
        -- Nothing was updated, return empty result set
