CREATE OR REPLACE FUNCTION "__mj"."spCreateWorkspaceItem"(
    p_id UUID DEFAULT NULL,
    p_name varchar(255) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_workspaceid UUID DEFAULT NULL,
    p_resourcetypeid UUID DEFAULT NULL,
    p_resourcerecordid_clear boolean DEFAULT false,
    p_resourcerecordid varchar(2000) DEFAULT NULL,
    p_sequence int DEFAULT NULL,
    p_configuration_clear boolean DEFAULT false,
    p_configuration TEXT DEFAULT NULL
) RETURNS SETOF "__mj"."vwWorkspaceItems" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."WorkspaceItem"
        (
            "ID",
            "Name",
                "Description",
                "WorkspaceID",
                "ResourceTypeID",
                "ResourceRecordID",
                "Sequence",
                "Configuration"
        )
    VALUES
        (
            v_new_id,
            p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                p_workspaceid,
                p_resourcetypeid,
                CASE WHEN p_resourcerecordid_clear = true THEN NULL ELSE COALESCE(p_resourcerecordid, NULL) END,
                p_sequence,
                CASE WHEN p_configuration_clear = true THEN NULL ELSE COALESCE(p_configuration, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwWorkspaceItems"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
